PlayScreen = ControlScreen.extend({
  show_hitbox: false,
  init: function() {
    this.parent();
    this._pauseable = true;
    return this._plays_music = true;
  },
  onResetEvent: function() {
    if (!me.game.HUD) {
      me.game.addHUD(0, 186, 336, 14, "#000000");
      me.game.HUD.addItem("score", new ScoreObject(336, 6));
    }
    me.levelDirector.loadLevel("level1");
    level_monitor = new LevelMonitor(the_doors);
    me.game.HUD.visible = config.context[config.context.active].hud.visible;
    if (player.music_enabled) {
      player.play();
    }
    // disable key-locking
    me.input.bindKey(me.input.KEY.UP, "up", false);
    return me.input.bindKey(me.input.KEY.DOWN, "down", false);
  },
  update: function() {
    Utils.sortEntities();
    if (me.input.isKeyPressed('hitbox')) {
      this.show_hitbox = !this.show_hitbox;
    }
    me.debug.renderHitBox = this.show_hitbox;
    return this.parent();
  }
});

Player = Object.extend({
  effects_enabled: true,
  music_enabled: true,
  MUSIC_PLAYING: 0,
  MUSIC_STOPPED: 1,
  MUSIC_PAUSED: 2,
  music_state: null,
  init: function() {
    return this.music_state = this.MUSIC_STOPPED;
  },
  play: function() {
    if (!this.music_enabled) {
      return;
    }
    if (this.music_state === this.MUSIC_PAUSED) {
      me.audio.resumeTrack();
    } else {
      me.audio.playTrack("game_music");
    }
    return this.music_state = this.MUSIC_PLAYING;
  },
  stop: function() {
    me.audio.stopTrack();
    return this.music_state = this.MUSIC_STOPPED;
  },
  pause: function() {
    me.audio.pauseTrack();
    return this.music_state = this.MUSIC_PAUSED;
  },
  finale: function(name) {
    if (!this.music_enabled) {
      return;
    }
    this.stop();
    this.music_state = this.MUSIC_PLAYING;
    return me.audio.play(name, false, function() {
      return this.music_state = this.MUSIC_STOPPED;
    });
  },
  effect: function(name) {
    if (this.effects_enabled) {
      return me.audio.play(name);
    }
  },
  musicEnabledToggle: function() {
    return this.music_enabled = !this.music_enabled;
  },
  effectsEnabledToggle: function() {
    return this.effects_enabled = !this.effects_enabled;
  }
});

LevelMonitor = Object.extend({
  doors: null,
  enemy_activity_ticks: null,
  countdown_ticks: null,
  init: function(doors) {
    return this.doors = doors;
  },
  enemy_activity: function() {
    return this.enemy_activity_ticks = this.doors.ticks;
  },
  update: function() {
    if (this.doors.opened && this.doors.inViewport() && !this.countdown_ticks) {
      this.countdown_ticks = this.doors.ticks;
    }
    if (!this.doors.inViewport()) {
      // For when hero is respawn
      this.countdown_ticks = null;
    }
    if (!this.doors.opened) {
      // For when level is reloaded
      return this.countdown_ticks = null;
    }
  },
  completed: function() {
    return this.enemy_activity_ticks && (this.enemy_activity_ticks + 120) < this.doors.ticks && this.countdown_ticks && (this.countdown_ticks + 100) < this.doors.ticks;
  }
});

main = function() {
  var app;
  app = new App();
  return app.onload();
};
